/* eslint-disable eslint-comments/disable-enable-pair */
/* eslint-disable jsx-a11y/no-noninteractive-element-interactions */
/* eslint-disable jsx-a11y/click-events-have-key-events */
import { TriangleAlert } from "lucide-react";
import React, { useCallback } from "react";
import {
  stopUnlockDialogClick,
  unlockCancelButtonClass,
  unlockDialogClassName,
  unlockHeaderBorderClass,
  unlockHeaderInnerClass,
  unlockHeaderTextClass,
  unlockMessageClass,
  unlockMessageErrorClass,
  unlockPrimaryButtonClass,
} from "./unlockModalStyles";

type HintConfirmationModalProps = {
  open: boolean;
  hintCost: number;
  availableCurrency: number;
  insufficientCurrency: boolean;
  onConfirm: () => void;
  onCancel: () => void;
  confirmDisabled?: boolean;
};

const HintConfirmationModal = ({
  open,
  hintCost,
  availableCurrency,
  insufficientCurrency,
  onConfirm,
  onCancel,
  confirmDisabled = false,
}: HintConfirmationModalProps) => {
  const handleOverlayClick = useCallback(
    (event: React.MouseEvent<HTMLDivElement>) => {
      if (event.target === event.currentTarget) {
        onCancel();
      }
    },
    [onCancel],
  );

  if (!open) {
    return null;
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 px-4"
      role="presentation"
      onClick={handleOverlayClick}
    >
      <div
        className={unlockDialogClassName}
        role="dialog"
        aria-modal="true"
        aria-labelledby="hint-confirmation-title"
        onClick={stopUnlockDialogClick}
      >
        <div className="flex max-w-full flex-col gap-5">
          <div className={unlockHeaderBorderClass}>
            <div className={unlockHeaderInnerClass}>
              <TriangleAlert className="h-6 w-6 text-[#153A62]" />
              <span className={unlockHeaderTextClass}>
                Spend {hintCost} RP?
              </span>
            </div>
          </div>
          <div className="flex flex-col gap-2 whitespace-normal px-4">
            <h3
              id="hint-confirmation-title"
              className="font-headline text-xl text-white"
            >
              Submit this hint request?
            </h3>
            <p className={unlockMessageClass}>
              Requesting this hint will spend {hintCost} RP. You have{" "}
              {availableCurrency} RP available.
            </p>
            {insufficientCurrency ? (
              <p className={unlockMessageErrorClass}>
                You need more RP to submit this hint.
              </p>
            ) : null}
          </div>
          <div className="flex flex-wrap justify-end gap-3 sm:flex-nowrap">
            <button
              className={unlockCancelButtonClass}
              onClick={onCancel}
              type="button"
            >
              Cancel
            </button>
            <button
              className={unlockPrimaryButtonClass}
              onClick={onConfirm}
              disabled={confirmDisabled || insufficientCurrency}
              type="button"
            >
              Confirm and submit
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default HintConfirmationModal;
