import {
  type HintResource,
  type HintLogEntry,
  newClient,
  type TeamHuntState,
  get_hint_resource_status,
} from "@hunt/public-client";
import { PuzzleInfoBox } from "@hunt/puzzle-components";
import { ConditionalTooltip } from "@hunt/shadcn";
import {
  ArrowRight,
  ChevronDown,
  ChevronUp,
  TriangleAlert,
} from "lucide-react";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import { getHintResourceHintsPath } from "../../utils/hints";
import apiUrl from "../utils/apiUrl";
import { IS_STATIC_SITE, staticDisabledMessage } from "../utils/staticSite";
import HintConfirmationModal from "./HintConfirmationModal";
import { TeamStateProvider } from "./TeamStateProvider";
type Hints = HintLogEntry[];

type Hint = HintLogEntry;

type FormState = "idle" | "submitting" | "error";

type HintThread = {
  request?: Extract<HintLogEntry, { type: "hint_requested" }>;
  response?: Extract<HintLogEntry, { type: "hint_responded" }>;
};

function formatHintTimestamp(t: string) {
  return new Date(t).toLocaleString("en-US", {
    weekday: "long",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

const getThreadTimestamp = (thread: HintThread) =>
  thread.response?.timestamp ?? thread.request?.timestamp ?? "";

const getThreadKey = (thread: HintThread) =>
  thread.response?.id ?? thread.request?.id ?? -1;

const getThreadTimestampMs = (thread: HintThread) => {
  const timestamp = getThreadTimestamp(thread);
  const ms = timestamp ? new Date(timestamp).getTime() : NaN;
  return Number.isFinite(ms) ? ms : 0;
};

const buildHintThreads = (hints: Hints): HintThread[] => {
  const threads: HintThread[] = [];
  let current: HintThread | undefined;

  hints.forEach((hint) => {
    if (hint.type === "hint_requested") {
      if (current && (current.request || current.response)) {
        threads.push(current);
      }
      current = { request: hint };
    } else {
      if (current && !current.response) {
        current.response = hint;
        threads.push(current);
        current = undefined;
      } else {
        threads.push({ response: hint });
        current = undefined;
      }
    }
  });

  if (current) {
    threads.push(current);
  }

  return threads;
};

const HintForm = ({
  hintResource,
  onReceiveHintsFromApi,
  hintCost,
  teamState,
}: {
  hintResource: HintResource;
  onReceiveHintsFromApi: (hints: Hint[]) => void;
  hintCost: number;
  teamState: TeamHuntState;
}) => {
  const isAtlasOfMosaicsRound =
    hintResource.type === "round" && hintResource.slug === "atlas_of_mosaics";

  const [hintInput, setHintInput] = useState<string>("");
  const [formState, setFormState] = useState<FormState>("idle");
  const [formError, setFormError] = useState<string | undefined>(undefined);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const availableCurrency = teamState.currency;
  const insufficientCurrency = hintCost > 0 && availableCurrency < hintCost;
  const shouldConfirmSpend = hintCost > 0;
  const isStaticSite = IS_STATIC_SITE;

  const onInputChanged = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      setHintInput(e.target.value);
    },
    [],
  );

  const submitHintRequest = useCallback(async () => {
    setFormState("submitting");
    setFormError(undefined);
    let result;
    try {
      const apiClient = newClient(apiUrl(), undefined);
      result = await apiClient.submitHintRequest({
        body: {
          hint_resource: hintResource,
          request: hintInput,
        },
      });
    } catch {
      setFormError("Network request failed");
      setFormState("error");
      return;
    }
    if (result.status === 200) {
      const parsedResult = result.body;
      setHintInput("");
      setFormError(undefined);
      setFormState("idle");
      onReceiveHintsFromApi(parsedResult.hints);
      return;
    }
    if (
      result.status === 400 &&
      result.body?.code === "INSUFFICIENT_CURRENCY"
    ) {
      setFormError("You need more RP to request this hint.");
    } else if (result.status === 409) {
      setFormError(
        "You already have an outstanding hint request. Please wait for a response before submitting another.",
      );
    } else {
      setFormError(
        "Unable to submit your hint request. Please refresh the page and try again.",
      );
    }
    setFormState("error");
  }, [hintInput, hintResource, onReceiveHintsFromApi]);

  const onSubmit = useCallback(
    (e: React.FormEvent<HTMLFormElement>) => {
      e.preventDefault();
      if (formState === "submitting") {
        return;
      }
      setFormError(undefined);
      if (shouldConfirmSpend) {
        if (insufficientCurrency) {
          setFormError(
            `You need ${hintCost} RP to request this hint but only have ${availableCurrency} RP.`,
          );
          return;
        }
        setConfirmOpen(true);
        return;
      }
      void submitHintRequest();
    },
    [
      availableCurrency,
      formState,
      hintCost,
      insufficientCurrency,
      shouldConfirmSpend,
      submitHintRequest,
    ],
  );

  const onConfirmSubmit = useCallback(() => {
    setConfirmOpen(false);
    void submitHintRequest();
  }, [submitHintRequest]);

  const onCancelConfirm = useCallback(() => {
    setConfirmOpen(false);
  }, []);

  const formDisabled = formState === "submitting";
  const submitDisabled = formDisabled || insufficientCurrency;
  if (isStaticSite) {
    return (
      <div className="rounded-md border border-gold-300 bg-gold-50 p-3 text-sm text-gold-900">
        {staticDisabledMessage("Hints")}
      </div>
    );
  }
  return (
    <>
      <form
        method="post"
        action="#"
        onSubmit={onSubmit}
        className="flex flex-col gap-4 text-left"
      >
        <div className="flex flex-col gap-2">
          <h2 className="text-2xl font-bold">Request a new hint</h2>
          {hintCost > 0 ? (
            <p className="flex items-center gap-2 rounded-md border border-gold-700 bg-gold-100 p-2 text-xs font-semibold text-gold-800">
              <TriangleAlert
                aria-hidden
                className="h-4 w-4 shrink-0 text-red-700"
              />
              <span>
                Note: Requesting a hint for this {hintResource.type} will deduct{" "}
                {hintCost} RP.
              </span>
            </p>
          ) : null}
          <p className="text-sm text-black/80">
            Share what you&apos;ve tried, where you&apos;re stuck, and how we
            can help you move forward.
            {isAtlasOfMosaicsRound ? " Include the regions/levels, too." : ""}
          </p>
        </div>
        <div className="flex flex-col gap-3">
          <textarea
            id="hint-input"
            name="hint"
            required
            disabled={formDisabled}
            value={hintInput}
            onChange={onInputChanged}
            className="w-full min-h-[200px] resize-vertical rounded-xl border-2 border-[#153A62] bg-[#153A62A8] px-4 py-3 text-white placeholder-white/80 shadow-[0_4px_4px_0px_rgba(0,0,0,0.25)] transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#3C87D2] focus-visible:ring-offset-2 focus-visible:ring-offset-white disabled:cursor-not-allowed disabled:opacity-60"
            maxLength={2500}
            placeholder="Type your request here..."
          />
          {formError ? (
            <p className="text-sm font-semibold text-red-500">{formError}</p>
          ) : null}
          <div className="flex flex-wrap items-center justify-between gap-3">
            <p className="text-xs text-[#153A62] break-words">
              There&apos;s a 2,500 character limit. If you need more space, link
              a doc or sheet and make sure link sharing is on.
            </p>
            <ConditionalTooltip
              tooltip={
                hintCost > 0 && insufficientCurrency
                  ? `You need ${hintCost} RP to request this hint but only have ${availableCurrency} RP.`
                  : undefined
              }
            >
              <button
                type="submit"
                disabled={submitDisabled}
                className="inline-flex items-center gap-2 rounded-full border-2 border-[#153A62] bg-[#153A62] px-6 py-2 text-lg font-semibold text-white shadow-[0_4px_4px_0px_rgba(0,0,0,0.25)] transition hover:brightness-110 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#3C87D2] focus-visible:ring-offset-2 focus-visible:ring-offset-white disabled:cursor-not-allowed disabled:opacity-60"
              >
                <span>Submit</span>
                <ArrowRight className="h-5 w-5" aria-hidden />
              </button>
            </ConditionalTooltip>
          </div>
        </div>
      </form>
      <HintConfirmationModal
        open={shouldConfirmSpend && confirmOpen}
        hintCost={hintCost}
        availableCurrency={availableCurrency}
        insufficientCurrency={insufficientCurrency}
        onConfirm={onConfirmSubmit}
        onCancel={onCancelConfirm}
        confirmDisabled={formDisabled}
      />
    </>
  );
};

const HintHistoryCard = ({
  thread,
  isOpen,
  onToggle,
}: {
  thread: HintThread;
  isOpen: boolean;
  onToggle: () => void;
}) => {
  const timestamp = getThreadTimestamp(thread);
  const requestText = thread.request?.data.request;
  return (
    <div className="overflow-hidden rounded-2xl border border-[#2C599C] shadow-[0_4px_4px_0px_rgba(0,0,0,0.25)]">
      <button
        type="button"
        onClick={onToggle}
        aria-expanded={isOpen}
        className="flex w-full items-start justify-between gap-3 bg-[#BEF1FFCC] p-4 text-left transition hover:brightness-[0.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#3C87D2] focus-visible:ring-offset-2 focus-visible:ring-offset-white"
      >
        <div className="flex flex-1 flex-col gap-2">
          <div className="flex flex-wrap items-center gap-2">
            <span className="text-lg font-semibold text-[#3C87D2]">
              Hint request
            </span>
            {timestamp && (
              <span className="text-sm italic text-[#3C87D2]/80">
                Requested {formatHintTimestamp(timestamp)}
              </span>
            )}
          </div>
          {isOpen && requestText ? (
            <p className="whitespace-pre-wrap text-sm text-[#153A62]">
              {requestText}
            </p>
          ) : null}
        </div>
        <span className="mt-1 flex h-9 w-9 items-center justify-center rounded-full border border-[#2C599C] bg-white/70 text-[#3C87D2] shadow-inner">
          {isOpen ? (
            <ChevronUp className="h-5 w-5" aria-hidden />
          ) : (
            <ChevronDown className="h-5 w-5" aria-hidden />
          )}
        </span>
      </button>
      {isOpen && thread.response && (
        <div className="bg-[#2C599C] p-4 text-white">
          <div
            className="leading-relaxed text-white"
            dangerouslySetInnerHTML={{
              __html: thread.response.data.response,
            }}
          />
        </div>
      )}
    </div>
  );
};

const HintHistory = ({ hints }: { hints: Hints }) => {
  const threads = useMemo(() => buildHintThreads(hints), [hints]);
  const sortedThreads = useMemo(
    () =>
      [...threads].sort(
        (a, b) => getThreadTimestampMs(b) - getThreadTimestampMs(a),
      ),
    [threads],
  );

  const [openThreads, setOpenThreads] = useState<Set<number>>(
    () =>
      new Set(sortedThreads.slice(0, 1).map((thread) => getThreadKey(thread))),
  );

  useEffect(() => {
    if (sortedThreads.length === 0) {
      return;
    }
    const latestKey = getThreadKey(sortedThreads[0]);
    if (latestKey === -1) {
      return;
    }
    setOpenThreads((prev) => {
      if (prev.has(latestKey)) {
        return prev;
      }
      const next = new Set(prev);
      next.add(latestKey);
      return next;
    });
  }, [sortedThreads]);

  if (sortedThreads.length === 0) {
    return null;
  }

  return (
    <div className="flex flex-col gap-3">
      <h2 className="text-xl font-bold">Previous Hints</h2>
      <div className="flex flex-col gap-4">
        {sortedThreads.map((thread) => {
          const key = getThreadKey(thread);
          const isOpen = openThreads.has(key);
          return (
            <HintHistoryCard
              key={key}
              thread={thread}
              isOpen={isOpen}
              onToggle={() => {
                setOpenThreads((prev) => {
                  const next = new Set(prev);
                  if (next.has(key)) {
                    next.delete(key);
                  } else {
                    next.add(key);
                  }
                  return next;
                });
              }}
            />
          );
        })}
      </div>
    </div>
  );
};

const ResourceHints = ({
  hintResource,
  hints,
  onReceiveHintsFromApi,
  teamState,
  hintCost,
}: {
  hintResource: HintResource;
  hints: Hints;
  onReceiveHintsFromApi: (hints: Hints) => void;
  teamState: TeamHuntState;
  hintCost: number;
}) => {
  let form: React.JSX.Element | null = null;
  const isAtlasOfMosaicsRound =
    hintResource.type === "round" && hintResource.slug === "atlas_of_mosaics";
  const roundHintGuidance =
    hintResource.type === "puzzle" ? null : (
      <PuzzleInfoBox copyable={false} className="w-full">
        {isAtlasOfMosaicsRound ? (
          <>
            <p>
              This hint page is intended to be used for hint requests on Atlas
              of Mosaics non-meta puzzles.
            </p>
            <p>
              Do not request hints for more than one puzzle at a time, though
              hinting for multiple levels of the same puzzle is acceptable.
            </p>
            <p>
              To help us help you better, please specify the regions/levels you
              are requesting a hint for and share with us screenshots of your
              current progress.
            </p>
          </>
        ) : (
          <p>
            This hint page is intended for requesting hints on round-level
            mechanics. This includes round navigation and puzzle discovery (e.g.
            MonQuest), but not on any puzzles themselves.
          </p>
        )}
      </PuzzleInfoBox>
    );

  const hintRequestOpen = useMemo(() => {
    const lastHint = hints[hints.length - 1];
    return lastHint ? lastHint.type === "hint_requested" : false;
  }, [hints]);

  const hintResourceStatus = useMemo(
    () => get_hint_resource_status(hintResource, teamState),
    [hintResource, teamState],
  );
  const hintResourceSolved = hintResourceStatus === "solved";

  if (hintResourceSolved) {
    form = null;
  } else if (hintRequestOpen) {
    form = (
      <p className="text-sm border border-gold-700 text-gold-800 p-4 bg-gold-200 rounded-sm">
        Hunt HQ is reviewing your request and will get back to you shortly.
        You’ll receive an email and a notification when they respond.
      </p>
    );
  } else if (teamState.outstanding_hint_requests.length > 0) {
    const outstanding = teamState.outstanding_hint_requests[0];
    const outstandingLabel =
      outstanding.type === "puzzle"
        ? `another puzzle (${outstanding.slug})`
        : `${outstanding.type} ${outstanding.slug}`;
    const outstandingHref = getHintResourceHintsPath(outstanding);
    form = (
      <p className="text-sm border border-gold-700 text-gold-800 p-4 bg-gold-200 rounded-sm">
        You have an outstanding hint request for{" "}
        {outstandingHref ? (
          <a
            href={outstandingHref}
            className="underline text-inherit"
            aria-label={`View outstanding hint request for ${outstandingLabel}`}
          >
            {outstandingLabel}
          </a>
        ) : (
          outstandingLabel
        )}
        . Please wait for a response to that request before submitting another
        hint request.
      </p>
    );
  } else {
    form = (
      <HintForm
        hintResource={hintResource}
        onReceiveHintsFromApi={onReceiveHintsFromApi}
        hintCost={hintCost}
        teamState={teamState}
      />
    );
  }
  return (
    <section id="puzzle-hint-section" className="text-black px-2">
      <TeamStateProvider teamState={teamState}>
        <div className="mx-auto flex w-full max-w-5xl flex-col gap-6">
          {roundHintGuidance}
          {form}
          <HintHistory hints={hints} />
        </div>
      </TeamStateProvider>
    </section>
  );
};

export default ResourceHints;
