import {
  hintResourceKey,
  type HintLogEntry,
  type HintResource,
  type TeamHuntState,
} from "@hunt/public-client";
import React, { useState } from "react";
import { hydrateRoot } from "react-dom/client";
import ResourceHints from "../components/Hints";
import useAppendDataset from "./useAppendDataset";
import useDataset from "./useDataset";

type Hints = HintLogEntry[];
type Hint = Hints[number];

const mergeHints = (oldHints: Hint[], newHints: Hint[]): Hint[] => {
  // Merge the previous guess set and the new one together, retaining any common entries exactly once.
  const ids = new Set();
  const mergedHints: Hint[] = [];
  const processHint = (hint: Hint) => {
    if (!ids.has(hint.id)) {
      ids.add(hint.id);
      mergedHints.push(hint);
    }
  };
  oldHints.forEach(processHint);
  newHints.forEach(processHint);
  // Sort by id
  mergedHints.sort((a, b) => a.id - b.id);
  return mergedHints;
};

const HintsManager = ({
  initialHints,
  initialTeamState,
  hintResource,
  hintCost,
}: {
  initialHints: Hints;
  initialTeamState: TeamHuntState;
  hintResource: HintResource;
  hintCost: number;
}) => {
  const websocketHints = useAppendDataset(
    "hint_log",
    { slug: hintResourceKey(hintResource) },
    initialHints,
  );
  const [apiHints, setApiHints] = useState<Hint[]>([]);

  const teamState = useDataset("team_state", undefined, initialTeamState);

  return (
    <ResourceHints
      hintResource={hintResource}
      hints={mergeHints(apiHints, websocketHints)}
      onReceiveHintsFromApi={setApiHints}
      teamState={teamState}
      hintCost={hintCost}
    />
  );
};

const hintsElem = document.getElementById("hints");
if (hintsElem) {
  const initialWindow = window as unknown as {
    initialHints: Hints;
    initialTeamState: TeamHuntState;
    hintResource?: HintResource;
    puzzleSlug?: string;
    hintCost?: number;
  };
  const initialHints = initialWindow.initialHints;
  const initialTeamState = initialWindow.initialTeamState;
  const hintResource =
    initialWindow.hintResource ??
    (initialWindow.puzzleSlug
      ? ({ type: "puzzle", slug: initialWindow.puzzleSlug } as HintResource)
      : undefined);
  const hintCost = initialWindow.hintCost ?? 0;

  if (!hintResource) {
    console.error("Couldn't mount hints because no hint resource found");
  } else {
    hydrateRoot(
      hintsElem,
      <HintsManager
        initialHints={initialHints}
        initialTeamState={initialTeamState}
        hintResource={hintResource}
        hintCost={hintCost}
      />,
    );
  }
} else {
  console.error("Couldn't mount hints because #hints was nowhere to be found");
}
